//! `record_thought` takes Borsh. This fixture was produced by `thoughtBorsh` in
//! pit/brain/proof.mjs; decoding it here proves the brain and the contract
//! agree on the byte layout. (The sandbox test covers the real call.)

#![cfg(feature = "unit-tests")]

use near_sdk::borsh::BorshDeserialize;
use pit::ThoughtInput;

const FROM_BRAIN: &str = "";

#[test]
fn brain_encodes_thoughts_the_contract_reads() {
    let bytes = hex::decode(FROM_BRAIN).unwrap();
    let t = ThoughtInput::try_from_slice(&bytes).expect("exact layout, no trailing bytes");
    assert_eq!(t.text, "I ate today. 🧠 smarter");
    assert_eq!(t.model, "Qwen/Qwen3.8-27B");
    assert_eq!(t.chat_id, "chatcmpl-1");
    assert_eq!(t.signature_kind, "provider_tee");
    assert_eq!(t.request_hash, "11".repeat(32));
    assert_eq!(t.response_hash, "22".repeat(32));
    assert_eq!(t.signature_hex, "ab".repeat(64));
    assert_eq!(t.signing_address, "cd".repeat(32));
    assert_eq!(t.attestation_hash.as_deref(), Some("ef".repeat(32).as_str()));
}
